      name: 'file_metadata',
      description: 'Return metadata (relative path, byte size, lowercase extension) for a file under the workspace data directory.',
      inputSchema: {
        type: 'object',
        properties: {
          path: {
            type: 'string',
            description: 'Relative path of the file under the data directory.'
          }
        },
        required: ['path'],
        additionalProperties: false
      }
    }
  ];
}

function assertStringPath(p) {
  if (typeof p !== 'string' || p.length === 0) {
    throw new Error('Path is required');
  }
}

