+          }
+        },
+        required: ['path'],
+        additionalProperties: false
+      }
+    }
+  ];
+}
+
+function assertStringPath(p) {
+  if (typeof p !== 'string' || p.length === 0) {
+    throw new Error('Path is required');
+  }
+}
+
+function resolveWithinData(rel) {
+  const normalized = path.normalize(rel).replace(/^([/\\]+)/, '');
+  const resolved = path.resolve(DATA_DIR, normalized);
+  const relToData = path.relative(DATA_DIR, resolved);
+  if (relToData.startsWith('..') || path.isAbsolute(relToData)) {
+    throw new Error('Path traversal is not allowed');
+  }
+  return { resolved, relToData };
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'file_metadata') {
+    throw new Error('Unknown tool: ' + name);
+  }
+
+  assertStringPath(args.path);
+  const { resolved, relToData } = resolveWithinData(args.path);
+
+  let stat;
+  try {
+    stat = await fs.stat(resolved);
+  } catch (e) {
+    throw new Error('File not found: ' + args.path);
+  }
+  if (!stat.isFile()) {
+    throw new Error('Not a file: ' + args.path);
+  }
+
+  const ext = path.extname(relToData).toLowerCase();
+  const text = [
+    'path: ' + relToData,
+    'size: ' + stat.size,
+    'extension: ' + ext
+  ].join('\n');
+
+  return {
+    content: [{ type: 'text', text }]
+  };
+}
